			},
			{
				Pattern: &ast.WildcardPattern{},
				Body: []ast.Statement{
					&ast.ExpressionStatement{Expression: &ast.Identifier{Name: "other"}},
				},
			},
		},
	}

	// Program 생성
	program := &ast.Program{
		Definitions: []ast.Definition{},
		MainBody: []ast.Statement{
			matchStmt,
		},
