// ArrayExpression represents an array literal
type ArrayExpression struct {
	Elements []Expression
}

func (*ArrayExpression) expressionNode() {}

// StructExpression represents a struct literal
type StructExpression struct {
	Name   string
	Fields map[string]Expression
}

func (*StructExpression) expressionNode() {}

// Type represents a type
type Type struct {
	Name       string
	IsOption   bool
	IsResult   bool
	ErrorType  *Type
	ElementType *Type
	IsArray    bool
	IsPrimitive bool
	IsFunction bool
	ParamTypes []Type
	ReturnType *Type
}

// String returns string representation of type
func (t *Type) String() string {
	if t == nil {
		return "unknown"
	}

	if t.IsOption {
		return "?" + t.ElementType.String()
	}
	if t.IsResult {
		errStr := "String"
		if t.ErrorType != nil {
			errStr = t.ErrorType.String()
		}
		return "Result(" + t.ElementType.String() + ", " + errStr + ")"
	}
	if t.IsArray {
		return "[]" + t.ElementType.String()
	}
	if t.IsFunction {
		return "fn"
	}
	return t.Name
}

