   575→  private formatBytes(bytes: number): string {
   576→    if (bytes === 0) return '0 B';
   577→
   578→    const k = 1024;
   579→    const sizes = ['B', 'KB', 'MB', 'GB'];
   580→    const i = Math.floor(Math.log(bytes) / Math.log(k));
   581→
   582→    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
   583→  }
