   433→func (l *Lexer) skipWhitespaceAndComments() {
   434→	for !l.isAtEnd() {
   435→		switch l.current() {
   436→		case ' ', '\t', '\r':
   437→			l.advance()
   438→		case '\n':
   439→			l.line++
   440→			l.column = 0
   441→			l.advance()
   442→		case '/' :
   443→			if l.peekNext() == '/' {
   444→				// 한 줄 주석
   445→				for !l.isAtEnd() && l.current() != '\n' {
   446→					l.advance()
   447→				}
   448→			} else if l.peekNext() == '*' {
   449→				// 블록 주석
   450→				l.advance()
   451→				l.advance()
   452→				for !l.isAtEnd() {
   453→					if l.current() == '*' && l.peekNext() == '/' {
   454→						l.advance()
   455→						l.advance()
   456→						break
   457→					}
   458→					if l.current() == '\n' {
   459→						l.line++
   460→						l.column = 0
   461→					}
   462→					l.advance()
   463→				}
   464→			} else {
   465→				return
   466→			}
   467→		default:
   468→			return
   469→		}
   470→	}
   471→}
   472→
   473→func (l *Lexer) current() byte {
   474→	if l.isAtEnd() {
   475→		return 0
   476→	}
   477→	return l.input[l.pos]
   478→}
   479→
   480→func (l *Lexer) peekNext() byte {
   481→	if l.pos+1 >= len(l.input) {
   482→		return 0
   483→	}
   484→	return l.input[l.pos+1]
   485→}
   486→
   487→func (l *Lexer) isDigitAt(pos int) bool {
   488→	if pos >= len(l.input) {
   489→		return false
   490→	}
   491→	return unicode.IsDigit(rune(l.input[pos]))
   492→}
   493→
   494→func (l *Lexer) advance() {
   495→	if !l.isAtEnd() {
   496→		l.pos++
   497→		l.column++
   498→	}
   499→}
   500→
   501→func (l *Lexer) isAtEnd() bool {
   502→	return l.pos >= len(l.input)
   503→}
